/* Supabase Auth + revision-checked cloud snapshots; no passwords on this page. */
const learningStorageKeys=['ops-learning-v1','learning-hub-v1','learning-python-v1','reading-pages-v1','learning-resume-v1','ops-incidents-v1','learning-reader-v1'];
let accountApplying=false,accountClient=null,accountUser=null,accountReady=false,accountRevision=0,accountDirty=false,accountConflict=false,accountSyncing=false,accountEpoch=0,accountTimer=null,accountStatus='未登录，进度保存在本机。',accountNotes=[],accountNoteId=null,accountNoteDraft={title:'',content:''};
function localSnapshot(){return Object.fromEntries(learningStorageKeys.map(k=>[k,localStorage.getItem(k)]));}
function storeAccountMeta(){localStorage.setItem('learning-account-meta',JSON.stringify({user:accountUser?.id,revision:accountRevision,dirty:accountDirty}));}
function applySnapshot(payload){for(const key of learningStorageKeys)if(typeof payload?.[key]==='string')JSON.parse(payload[key]);accountApplying=true;try{for(const key of learningStorageKeys){const value=payload?.[key];if(typeof value==='string')localStorage.setItem(key,value);else localStorage.removeItem(key);}}finally{accountApplying=false;}}
function cloudStatus(text){accountStatus=text;document.querySelectorAll('[data-cloud-status]').forEach(n=>n.textContent=text);}
async function syncAccount(){if(!accountClient||!accountUser||!accountReady||accountConflict||accountSyncing||!accountDirty)return;accountSyncing=true;const epoch=accountEpoch;try{const {data,error}=await accountClient.rpc('save_learning_snapshot',{p_payload:localSnapshot(),p_revision:accountRevision});if(error)throw error;if(!data?.length){accountConflict=true;accountReady=false;cloudStatus('另一设备有新进度。请在个人账户中选择同步方式。');return;}accountRevision=Number(data[0].revision);accountDirty=accountEpoch!==epoch;storeAccountMeta();cloudStatus(accountDirty?'本机已有新修改，继续同步中。':'已同步至个人账户 · '+new Date().toLocaleTimeString());}catch{cloudStatus('云端暂时不可用，本机记录仍保留；可稍后重试同步。');}finally{accountSyncing=false;if(accountDirty&&accountReady&&!accountConflict)accountTimer=setTimeout(syncAccount,10000);}}
async function activateAccount(user){if(!user){accountUser=null;accountReady=false;cloudStatus('未登录，进度保存在本机。');return;}if(accountUser?.id===user.id)return;accountUser=user;cloudStatus('正在核对个人云端进度…');try{const {data,error}=await accountClient.from('learning_snapshots').select('payload,revision').eq('user_id',user.id).maybeSingle();if(error)throw error;const owner=localStorage.getItem('learning-account-owner'),meta=JSON.parse(localStorage.getItem('learning-account-meta')||'{}');if(owner!==user.id){localStorage.setItem(owner?'learning-account-backup:'+owner:'learning-guest-backup',JSON.stringify(localSnapshot()));localStorage.setItem('learning-account-owner',user.id);accountRevision=Number(data?.revision||0);accountDirty=false;accountReady=true;storeAccountMeta();applySnapshot(data?.payload||{});location.reload();return;}accountRevision=Number(meta.user===user.id?meta.revision:0);accountDirty=meta.user===user.id&&meta.dirty===true;if(data&&Number(data.revision)!==accountRevision){if(accountDirty){accountConflict=true;accountReady=false;cloudStatus('云端与本机都有变更，请选择保留方式。');}else{accountRevision=Number(data.revision);storeAccountMeta();applySnapshot(data.payload);location.reload();return;}}else{accountReady=true;cloudStatus(accountDirty?'本机修改等待同步。':'已登录 · 学习进度将自动同步。');if(accountDirty)await syncAccount();}await loadAccountNotes();if(view==='account')render();}catch{accountReady=false;cloudStatus('账户已登录，但云端进度未就绪。请确认已执行数据库配置；本机学习仍可继续。');if(view==='account')render();}}
async function loadAccountNotes(){if(!accountUser)return;const {data,error}=await accountClient.from('study_notes').select('id,title,content,updated_at').eq('user_id',accountUser.id).order('updated_at',{ascending:false}).limit(100);if(error)throw error;accountNotes=data||[];}
function accountHTML(){const configured=!!accountClient;return `<main class="hub-main"><button class="text-button" data-hub="home">返回学习首页</button><h1>个人账户与学习笔记</h1><p data-cloud-status role="status">${esc(accountStatus)}</p>${accountUser?`<section class="section"><h2>${esc(accountUser.email||'已登录账户')}</h2><p>不同设备登录同一账户，可同步课程、阅读页码、草稿与答题结果。多设备同时修改时会提示选择，避免覆盖。</p><button class="primary" data-account="sync">重试同步</button><button class="secondary" data-account="load">载入云端进度</button>${accountConflict?'<button class="secondary" data-account="keep">保留本机进度并更新云端</button>':''}${localStorage.getItem('learning-guest-backup')?'<button class="secondary" data-account="import">导入登录前的本机进度</button>':''}<button class="secondary" data-account="logout">退出账户</button></section><section class="section"><h2>我的学习笔记</h2><p>记录今天学到的概念、命令、证据与没解决的问题。笔记仅供自己的账户读取。</p><label>标题<input id="account-note-title" maxlength="160" value="${esc(accountNoteDraft.title)}"></label><label>正文<textarea id="account-note-content" rows="9" maxlength="50000">${esc(accountNoteDraft.content)}</textarea></label><button class="primary" data-account="save-note">保存${accountNoteId?'修改':'新笔记'}</button><button class="secondary" data-account="new-note">写新笔记</button><div>${accountNotes.map(n=>`<article class="section"><h3>${esc(n.title)}</h3><small>${esc(new Date(n.updated_at).toLocaleString())}</small><pre class="note-content">${esc(n.content)}</pre><button class="secondary" data-account="edit-note" data-id="${esc(n.id)}">编辑这条笔记</button></article>`).join('')||'<p>还没有笔记，先写一句今天学到的内容。</p>'}</div></section>`:`<section class="section"><h2>登录个人账户</h2><p>跳转到 GitHub 官方页面登录。本站不会要求你填写 GitHub 密码。</p><button class="primary" data-account="login" ${configured?'':'disabled'}>使用 GitHub 登录</button><p>尚未配置登录时仍可在本机学习；登录后可选择导入原有进度。</p></section>`}</main>`;}
const accountBaseNav=hubNav;hubNav=function(){return accountBaseNav().replace('</nav>','<button class="text-button" data-account="open">个人账户 / 笔记</button></nav>');};
const accountBaseRender=render;render=function(){if(view==='account'){$('app').innerHTML=hubNav()+accountHTML();return;}accountBaseRender();const main=document.querySelector('main');if(main&&accountUser){const status=document.createElement('p');status.className='small-note';status.dataset.cloudStatus='';status.textContent=accountStatus;main.append(status);}};
document.addEventListener('input',e=>{if(e.target.id==='account-note-title')accountNoteDraft.title=e.target.value;if(e.target.id==='account-note-content')accountNoteDraft.content=e.target.value;});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-account]');if(!b)return;const action=b.dataset.account;try{
 if(action==='open'){view='account';render();return;}
 if(action==='login'){const {error}=await accountClient.auth.signInWithOAuth({provider:'github',options:{redirectTo:location.origin+location.pathname}});if(error)throw error;return;}
 if(action==='sync'){if(!accountReady)await activateAccountRetry();else await syncAccount();render();}
 if(action==='load'||action==='keep'){const {data,error}=await accountClient.from('learning_snapshots').select('payload,revision').eq('user_id',accountUser.id).maybeSingle();if(error)throw error;accountRevision=Number(data?.revision||0);accountConflict=false;accountReady=true;localStorage.setItem('learning-account-backup:'+accountUser.id,JSON.stringify(localSnapshot()));if(action==='load'){accountDirty=false;storeAccountMeta();applySnapshot(data?.payload||{});location.reload();return;}accountDirty=true;await syncAccount();render();}
 if(action==='import'){const payload=JSON.parse(localStorage.getItem('learning-guest-backup')||'null');if(!payload)return;localStorage.setItem('learning-account-backup:'+accountUser.id,JSON.stringify(localSnapshot()));applySnapshot(payload);accountDirty=true;accountEpoch++;storeAccountMeta();await syncAccount();location.reload();return;}
 if(action==='logout'){if(accountDirty){await syncAccount();if(accountDirty){cloudStatus('进度尚未同步，请先重试或载入云端解决冲突，再退出。');return;}}const {error}=await accountClient.auth.signOut();if(error)throw error;localStorage.removeItem('learning-account-owner');localStorage.removeItem('learning-account-meta');applySnapshot(JSON.parse(localStorage.getItem('learning-guest-backup')||'{}'));location.reload();return;}
 if(action==='new-note'){accountNoteId=null;accountNoteDraft={title:'',content:''};render();}
 if(action==='edit-note'){const n=accountNotes.find(n=>n.id===b.dataset.id);if(n){accountNoteId=n.id;accountNoteDraft={title:n.title,content:n.content};render();}}
 if(action==='save-note'){const title=accountNoteDraft.title.trim(),content=accountNoteDraft.content;if(!title)return toast('先给笔记写一个标题。');const payload={title,content,updated_at:new Date().toISOString()};const query=accountNoteId?accountClient.from('study_notes').update(payload).eq('id',accountNoteId).eq('user_id',accountUser.id):accountClient.from('study_notes').insert({...payload,user_id:accountUser.id});const {error}=await query;if(error)throw error;await loadAccountNotes();accountNoteId=null;accountNoteDraft={title:'',content:''};render();toast('笔记已保存到个人账户。');}
 }catch{cloudStatus('操作未完成，请检查网络或账户配置。草稿仍保留，请稍后重试。');if(view==='account')render();}});
async function activateAccountRetry(){const user=accountUser;accountUser=null;await activateAccount(user);}
if(window.LEARNING_ACCOUNT_CONFIG?.url&&window.LEARNING_ACCOUNT_CONFIG?.publishableKey&&globalThis.LearningSupabase){accountClient=LearningSupabase.createClient(window.LEARNING_ACCOUNT_CONFIG.url,window.LEARNING_ACCOUNT_CONFIG.publishableKey,{auth:{flowType:'pkce',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});accountClient.auth.onAuthStateChange((event,session)=>{setTimeout(()=>activateAccount(session?.user||null),0);});accountClient.auth.getSession().then(({data})=>activateAccount(data.session?.user||null));}
if(typeof Storage!=='undefined'){const accountStorageWrite=Storage.prototype.setItem;Storage.prototype.setItem=function(key,value){accountStorageWrite.call(this,key,value);if(this===localStorage&&learningStorageKeys.includes(key)&&accountUser&&!accountApplying&&localStorage.getItem('learning-account-owner')===accountUser.id){accountDirty=true;accountEpoch++;storeAccountMeta();clearTimeout(accountTimer);accountTimer=setTimeout(syncAccount,1500);cloudStatus('本机已保存，正在等待云端同步。');}};}
render();
